-- IMAGE 1 : Architecture (Wat Rong Khun)
INSERT INTO images (nom, fichier, texte, id_auteur) VALUES (
    'Wat Rong Khun', 
    'architecture.jpg', 
    'Un temple éclatant de blancheur se reflète dans un bassin tranquille. Les ornements ciselés, scintillant sous la lumière du soleil, donnent une impression d’irréalité. Des sculptures fines ornent les toits et les ponts, symbolisant la pureté et la sagesse. La symétrie du lieu crée un sentiment d’équilibre et de sérénité. La blancheur totale du temple évoque la spiritualité et la perfection. L''Architecture est l''art de concevoir des espaces qui répondent à la fonction, mais qui véhiculent aussi des idées. Le bâtiment est une Structure et un récit. Il transmet la culture et les croyances (comme ici le Wat Rong Khun). Il enseigne les principes de Lumière, d''ingénierie, et comment un lieu peut inspirer la Transcendance ou la spiritualité. C''est l''art Classique au service du quotidien.', 
    1
);

-- IMAGE 2 : Cinéma (Oppenheimer)
INSERT INTO images (nom, fichier, texte, id_auteur) VALUES (
    'Oppenheimer', 
    'cinema.jpg', 
    'Un personnage en costume sombre se détache sur un fond d’explosion lumineuse, symbole du feu atomique. La composition alterne entre ombre et lumière, tension et silence. Le visage concentré traduit la complexité morale du scientifique. L’arrière-plan dramatique renforce l’intensité de la scène. L’image capte la puissance du récit historique et la réflexion sur le pouvoir de la science. Le Cinéma est l''art total qui utilise l''image, le son et le Récit pour créer un Effet immersif. Le film est un puissant outil pour raconter l''Histoire. Il enseigne la mise en scène, le montage, et l''utilisation de la Lumière. Il met en lumière des figures ou des événements historiques, comme le fait Oppenheimer. Il est souvent un miroir des préoccupations de son Époque, cherchant un Visage ou une figure emblématique. L''utilisation d''Effet est cruciale dans sa production.', 
    2
);

-- IMAGE 3 : Histoire (La liberté guidant le peuple)
INSERT INTO images (nom, fichier, texte, id_auteur) VALUES (
    'La liberté guidant le peuple', 
    'histoire.jpg', 
    'Une femme brandissant le drapeau tricolore mène une foule en révolte. La fumée, les ruines et les corps jonchant le sol créent une atmosphère de chaos héroïque. Les couleurs chaudes dominent, soulignant la passion et la lutte. La composition diagonale donne un élan vers l’avenir. L’image symbolise la liberté, le courage et la mémoire révolutionnaire. L''Histoire est le Récit des événements passés, transmis par des documents, des artefacts et des œuvres d''art. Ce tableau de Delacroix est une Mémoire visuelle. L''Histoire enseigne l''analyse des sources, la compréhension de l''Époque et le contexte des changements politiques et sociaux. C''est le fondement de tout Récit et de tout Texte.', 
    3
);

-- IMAGE 4 : Littérature (Victor Hugo)
INSERT INTO images (nom, fichier, texte, id_auteur) VALUES (
    'Victor Hugo', 
    'litterature.jpg', 
    'Un portrait en noir et blanc d’un homme pensif, la main appuyée sur la tempe. Le fond sombre met en valeur la force du regard et la profondeur du visage. Sur la table, un manuscrit et une plume rappellent l’écriture et la réflexion. Les jeux de lumière accentuent le contraste entre ombre et inspiration. L’image incarne la puissance de la pensée et du verbe. La Littérature est l''art du Texte, le véhicule des grandes idées et de l''Expression humaine. La littérature est un Patrimoine immatériel. Elle enseigne l''art de l''Expression, la rhétorique et l''imagination. Les œuvres de Hugo sont des exemples de styles Classiques qui continuent de façonner la pensée moderne. Elle offre un aperçu d''une Époque.', 
    4
);

-- IMAGE 5 : Musique (Orchestre)
INSERT INTO images (nom, fichier, texte, id_auteur) VALUES (
    'Orchestre', 
    'musique.jpg', 
    'Une scène illuminée présente un orchestre en pleine symphonie. Les instruments brillent sous les projecteurs, les musiciens concentrés suivent la baguette du chef. Les cordes, cuivres et percussions se répondent dans un équilibre visuel et sonore. Le mouvement des bras et la lumière donnent une impression de rythme et d’unité. L’image évoque l’harmonie, la rigueur et la beauté du collectif. La Musique est l''art du son, du Rythme et de l''Harmonie, jouant sur l''émotion immédiate. L''orchestre est l''exemple parfait de l''Harmonie et de la coordination. Elle enseigne la structure (composition), le Rythme et la Mélodie. La musique classique est un vecteur de Diffusion culturel qui traverse les siècles, et sa performance est une forme de Portrait auditif de l''intention du compositeur.', 
    5
);

-- IMAGE 6 : Paysage (La nature sauvage suédoise -> Montagne)
INSERT INTO images (nom, fichier, texte, id_auteur) VALUES (
    'La nature sauvage suédoise', 
    'paysage.jpg', 
    'Une chaîne montagneuse s’élève dans la brume matinale, aux teintes bleutées et dorées. Les sommets enneigés se détachent du ciel clair, tandis qu’une vallée verdoyante s’étend à leurs pieds. La lumière du soleil souligne la texture rocheuse et la grandeur naturelle du lieu. L’atmosphère évoque la paix, la contemplation et la puissance de la nature. L’œil est guidé vers l''horizon, symbole d''élévation et de découverte. L''étude du Paysage (ici, la montagne) est essentielle pour comprendre notre rapport à l''environnement. Le paysage n''est pas qu''un décor ; c''est un miroir de l''Histoire et un sujet d''art. En histoire de l''art, il enseigne la Grandeur, l''échelle, et la composition. Il porte la mémoire des civilisations qui l''ont traversé. En sciences, il raconte la géologie et l''écologie.', 
    6
);

-- IMAGE 7 : Portrait (Mona Lisa)
INSERT INTO images (nom, fichier, texte, id_auteur) VALUES (
    'Mona Lisa', 
    'portrait.jpg', 
    'Le visage calme et mystérieux d’une femme, légèrement souriante, se détache sur un fond de paysage flou. Ses mains croisées, la douceur des tons et le regard direct créent une proximité intime avec le spectateur. Le sfumato enveloppe ses traits dans une lumière dorée. Les contrastes subtils de l’arrière-plan accentuent le mystère du personnage. L’ensemble dégage une impression d’équilibre, de grâce et de secret. Le Portrait est un pilier de l''art figuratif, avec la Joconde comme archétype du Mystère et de l''Expression. Le portrait sert à documenter l''Époque et à décoder l''Expression. Il enseigne l''anatomie, la psychologie et les codes sociaux d''une époque (costume, statut). La Joconde, en particulier, montre l''évolution de la technique (sfumato) et sa valeur culturelle inestimable.', 
    7
);

-- IMAGE 8 : Sport (Jeux Olympiques Paris 2024)
INSERT INTO images (nom, fichier, texte, id_auteur) VALUES (
    'Jeux Olympiques Paris 2024', 
    'sport.jpg', 
    'Cinq anneaux colorés entrelacés se détachent sur un fond clair ou un ciel bleu. Leurs couleurs vives symbolisent l’union des continents et la diversité des peuples. L’image respire la vitalité, l’énergie et la fraternité. Derrière, un stade ou un paysage urbain suggère l’élan collectif des Jeux. L’ensemble traduit la compétition, la paix et la performance humaine. Le Sport est un fait social, culturel et historique, bien plus qu''une simple compétition. Le sport exige Performance et obéit à une Structure de règles. Il transmet les valeurs d''équipe, d''effort, et de Rythme. Les Jeux Olympiques, en particulier, sont un vecteur culturel d''Action, liant l''histoire antique à la société contemporaine.', 
    8
);

-- IMAGE 9 : Statue (Moaï)
INSERT INTO images (nom, fichier, texte, id_auteur) VALUES (
    'Moaï', 
    'statue.jpg', 
    'Une statue monumentale en pierre grise se dresse sur une île balayée par le vent. Son visage impassible, sculpté avec des traits simples et puissants, regarde l’horizon. Le ciel nuageux accentue la solennité du monument. Autour, le sol rocailleux et l’herbe basse rappellent la rudesse du paysage. La présence du Moaï évoque la mémoire des ancêtres et la permanence du sacré. La Statue incarne la pérennité et la présence physique de l''art dans l''espace public. Les statues sont des monuments de Patrimoine. L''exemple du Moaï (ou de n''importe quelle sculpture) enseigne les techniques de taille, la symbolique religieuse ou politique, et la manière dont l''art s''intègre au paysage. Sa couleur Blanche et sa masse témoignent de son impact visuel et historique.', 
    9
);

-- IMAGE 10 : Technologie (Intelligence Artificielle)
INSERT INTO images (nom, fichier, texte, id_auteur) VALUES (
    'Intelligence Artificielle', 
    'technologie.jpg', 
    'Un visage stylisé, mi-humain mi-numérique, émerge d’un réseau lumineux de circuits. Les teintes bleues et argentées évoquent la modernité et le flux d’informations. Des lignes de code et des symboles mathématiques s’entrelacent dans le fond. L’œil du personnage, lumineux, symbolise la conscience artificielle. L’ensemble illustre la frontière entre l’humain et la machine. La Technologie, et notamment l''IA, est le moteur de l''Innovation et transforme notre rapport au monde. L''IA est l''outil de la Diffusion de la culture et de l''information. Elle pose des questions éthiques et philosophiques. Elle améliore la Performance dans divers domaines et crée de nouveaux Effets artistiques. L''enseignement se concentre sur la programmation, l''algorithmique et l''impact social de l''Innovation.', 
    8
);